function ensureTurnPlan(
  application
) {
  const existingState =
    getFrameHelmApplicationTurnState();


  if (
    existingState &&
    !existingState.ended
  ) {
    return existingState;
  }


  const token =
    application.getControlledToken();


  if (
    !token
  ) {
    ui.notifications.warn(
      "Select a mech or NPC token first."
    );

    return null;
  }


  const turnManager =
    getFrameHelmApplicationTurnStateManager();


  if (
    !turnManager
  ) {
    ui.notifications.error(
      "Frame Helm could not resolve the Turn state manager."
    );

    return null;
  }


  const combat =
    game.combat;

  const combatContext =
    combat?.started
      ? getFrameHelmApplicationCombatContext(
          combat
        )
      : {};


  return turnManager.ensureTurn({
    ...combatContext,

    tokenId:
      token.id ??
      token.document?.id ??
      combatContext.tokenId ??
      null,

    actorId:
      token.actor?.id ??
      combatContext.actorId ??
      null,

    sceneId:
      canvas?.scene?.id ??
      combatContext.sceneId ??
      null,

    speed:
      (() => {
        const numericSpeed =
          Number(
            token.actor?.system?.speed
          );

        return (
          Number.isFinite(
            numericSpeed
          ) &&
          numericSpeed >= 0
            ? numericSpeed
            : null
        );
      })()
  });
}


